package body can_fd_fi_register_wait_until_pkg is

  -- ---------------------------------------------------------------------------
  -- Wait until the 'CORE_INFO' register equals the given 'value'.
  procedure wait_until_can_fd_fi_CORE_INFO_equals(
    signal net : inout network_t;
    value : in can_fd_fi_CORE_INFO_t;
    base_address : in unsigned(32 - 1 downto 0) := (others => '0');
    bus_handle : in bus_master_t := register_bus_master;
    timeout : delay_length := max_timeout;
    message : string := ""
  ) is
    constant reg_value : register_t := to_slv(value);

    constant reg_index : can_fd_fi_register_range := can_fd_fi_CORE_INFO;
    constant reg_address : unsigned(32 - 1 downto 0) := base_address + to_unsigned(4 * reg_index, 32);

    constant register_array_message : string := "";
    function base_address_message return string is
    begin
      if base_address /= 0 then
        return " (at base address " & hex_image(std_logic_vector(base_address)) & ")";
      end if;

      return "";
    end function;
    constant base_message : string := (
      "Timeout while waiting for the 'CORE_INFO' register"
      & register_array_message
      & base_address_message
      & " to equal the given value: "
      & to_string(reg_value)
      & "."
    );
    function get_message return string is
    begin
      if message = "" then
        return base_message;
      end if;

      return base_message & " " & message & ".";
    end function;
  begin
    wait_until_read_equals(
      net => net,
      bus_handle => bus_handle,
      addr => std_ulogic_vector(reg_address),
      value => reg_value,
      timeout => timeout,
      msg => get_message
    );
  end procedure;

